/// <summary>
/// Exclude cancelled lines with excluded reason code
/// </summary>
[ExtensionOf(classStr(SalesFormletterParmData))]
final class METSalesFormletterParmData_Extension
{
}

Method.Source:
    /// <summary>
    /// Determines whether the parm line must be created.
    /// </summary>
    /// <param name = "_salesLineOrig">A <c>SalesLine</c> record.</param>
    /// <returns>true if the parm line must be created; otherwise, false.</returns>
    protected boolean mustCreateParmLine(SalesLine _salesLineOrig)
    {
        boolean mustCreateParmLine = next mustCreateParmLine(_salesLineOrig);

        if (mustCreateParmLine)
        {
            METCustParameters METCustParameters = METCustParameters::Find();

            if (METCustParameters.IncludeCancelledLines == NoYes::Yes && _salesLineOrig.SalesStatus == SalesStatus::Canceled)
            {
                if (METExcludedReasonCode::exist(METSalesLine::find(_salesLineOrig.RecId).ReasonId))
                {
                    mustCreateParmLine = false;
                }
            }
        
        }

        return mustCreateParmLine;
    }
